def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    mod = 1_000_000_007
    size = len(alphabet)
    char_index = {char: i for i, char in enumerate(alphabet)}

    children = [[-1] * size]
    terminal = [False]

    for word in banned:
        state = 0
        for char in word:
            index = char_index[char]
            if children[state][index] == -1:
                children[state][index] = len(children)
                children.append([-1] * size)
                terminal.append(False)
            state = children[state][index]
        terminal[state] = True

    failure = [0] * len(children)
    queue = deque()

    for index in range(size):
        child = children[0][index]
        if child == -1:
            children[0][index] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        terminal[state] |= terminal[failure[state]]

        for index in range(size):
            child = children[state][index]
            if child == -1:
                children[state][index] = children[failure[state]][index]
            else:
                failure[child] = children[failure[state]][index]
                queue.append(child)

    safe_states = [state for state in range(len(children)) if not terminal[state]]
    safe_index = {state: i for i, state in enumerate(safe_states)}
    count = len(safe_states)

    matrix = [[0] * count for _ in range(count)]
    for state in safe_states:
        source = safe_index[state]
        for target in children[state]:
            if not terminal[target]:
                matrix[source][safe_index[target]] += 1

    vector = [0] * count
    vector[safe_index[0]] = 1

    while n:
        if n & 1:
            result = [0] * count
            for i, value in enumerate(vector):
                if value:
                    for j, weight in enumerate(matrix[i]):
                        result[j] = (result[j] + value * weight) % mod
            vector = result

        n >>= 1
        if n:
            squared = [[0] * count for _ in range(count)]
            for i in range(count):
                for k, value in enumerate(matrix[i]):
                    if value:
                        for j, weight in enumerate(matrix[k]):
                            squared[i][j] = (
                                squared[i][j] + value * weight
                            ) % mod
            matrix = squared

    return sum(vector) % mod
